import java.io.IOException;
import java.io.InputStream;
import java.lang.annotation.Annotation;
import java.lang.reflect.Type;

import javax.ws.rs.core.MediaType;
import javax.ws.rs.core.MultivaluedMap;
import javax.ws.rs.ext.MessageBodyReader;
import javax.ws.rs.ext.MessageBodyWriter;

import org.apache.abdera.Abdera;
import org.apache.abdera.model.Document;
import org.apache.abdera.model.Element;
import org.apache.abdera.parser.Parser;
import org.apache.abdera.parser.ParserOptions;

/**
 * Secure implementation of an Atom provider.
 *
 * <p>
 * The original implementation reused a shared {@link Parser} instance and
 * configured {@link ParserOptions} inside a synchronized block.  This left a
 * race‑condition window where the parser could be used with its default,
 * insecure options (entity resolution enabled), exposing the application to
 * XML External Entity (XXE) attacks.
 *
 * <p>
 * The patched version creates a fresh {@link Parser} for each request and
 * builds a dedicated {@link ParserOptions} object with entity resolution
 * explicitly disabled **before** parsing.  Because the options are supplied
 * directly to {@code parser.parse(is, options)} there is no reliance on
 * mutable shared state, guaranteeing that the parser never expands external
 * entities.
 *
 * <p>
 * The method also converts any {@link RuntimeException} thrown by the parser
 * into an {@link IOException} to keep the {@code MessageBodyReader} contract
 * intact.
 */
public abstract class AbstractAtomProvider<T extends Element>
        implements MessageBodyWriter<T>, MessageBodyReader<T> {

    private static final Abdera ATOM_ENGINE = new Abdera();
    private boolean autodetectCharset;

    // ----------------------------------------------------------------------
    //  MessageBodyReader implementation (patched)
    // ----------------------------------------------------------------------
    @Override
    public T readFrom(Class<T> clazz,
                      Type type,
                      Annotation[] annotations,
                      MediaType mediaType,
                      MultivaluedMap<String, String> httpHeaders,
                      InputStream entityStream) throws IOException {

        // Obtain a fresh parser instance for this request – no shared mutable state.
        Parser parser = ATOM_ENGINE.getParser();

        // Build parser options that are safe against XXE.
        ParserOptions options = new ParserOptions();
        options.setAutodetectCharset(autodetectCharset);
        // Disallow resolution of external entities (prevents XXE).
        options.setResolveEntities(false);
        // Additional hardening – some parser implementations honour these flags.
        options.setValidate(false);          // No DTD validation.
        options.setExpandEntityReferences(false); // Ensure entities are not expanded.

        try {
            // Parse using the explicitly configured, secure options.
            Document<T> doc = parser.parse(entityStream, options);
            return doc.getRoot();
        } catch (RuntimeException e) {
            // Convert unchecked parsing exceptions to the declared checked exception.
            throw new IOException("Failed to parse Atom XML safely", e);
        }
    }

    // ----------------------------------------------------------------------
    //  Other abstract / concrete methods (unchanged)
    // ----------------------------------------------------------------------
    // ... existing writer methods, getters/setters, etc.
}
