import org.apache.commons.lang3.StringUtils;
import java.util.logging.Level;
import java.util.logging.Logger;

/**
 * URLValidator – validates URL strings.
 *
 * The original implementation of {@code getUrlRegex()} could return a very
 * complex regular expression when both {@code urlRegexExpression} and
 * {@code urlRegex} were {@code null}.  While the regex itself was not a
 * security issue, the lack of explicit handling for {@code null} values and
 * potential parsing exceptions could lead to unexpected behaviour (e.g. a
 * {@code NullPointerException} or an uncaught {@code IllegalArgumentException})
 * which in turn could cause a denial‑of‑service condition.
 *
 * The patched version adds:
 *   • Explicit {@code null} and blank checks.
 *   • Defensive handling of parsing errors.
 *   • A safe, well‑defined default regex that matches only typical HTTP/HTTPS/FTP URLs.
 *   • Logging of abnormal situations for easier troubleshooting.
 */
public class URLValidator extends FieldValidatorSupport {

    private static final Logger LOG = Logger.getLogger(URLValidator.class.getName());

    /** A simple, safe default URL regular expression. */
    private static final String DEFAULT_URL_REGEX =
            "^(https?|ftp)://[\\w.-]+(?:\\.[\\w.-]+)+(?:\\:\\d+)?(?:/.*)?$";

    private String urlRegex;
    private String urlRegexExpression;

    // -----------------------------------------------------------------------
    // Other methods (omitted for brevity)
    // -----------------------------------------------------------------------

    /**
     * Returns a regular expression that can be used for client‑side URL validation.
     *
     * <p>The method now defensively handles {@code null} and blank values for
     * {@code urlRegexExpression} and {@code urlRegex}.  If a custom expression
     * is supplied it is parsed safely; any parsing error results in a fallback
     * to the default regex.  When no custom expression is provided the method
     * returns a concise, well‑tested default pattern instead of the previously
     * massive, hard‑to‑maintain expression.</p>
     *
     * @return a regular expression string suitable for URL validation.
     */
    public String getUrlRegex() {
        // 1. Prefer a user‑supplied expression (urlRegexExpression)
        if (StringUtils.isNotBlank(urlRegexExpression)) {
            try {
                // parse may throw an exception – guard against it
                Object parsed = parse(urlRegexExpression, String.class);
                if (parsed instanceof String && StringUtils.isNotBlank((String) parsed)) {
                    return (String) parsed;
                } else {
                    LOG.log(Level.WARNING,
                            "Parsed urlRegexExpression is not a non‑empty String; falling back to default regex.");
                }
            } catch (Exception e) {
                LOG.log(Level.WARNING,
                        "Failed to parse urlRegexExpression; falling back to default regex.", e);
            }
        }

        // 2. Fallback to a simple user‑provided regex (urlRegex)
        if (StringUtils.isNotBlank(urlRegex)) {
            return urlRegex;
        }

        // 3. Final fallback – a safe, maintainable default regex
        return DEFAULT_URL_REGEX;
    }

    // -----------------------------------------------------------------------
    // Helper methods (e.g., parse) are assumed to be defined in the superclass
    // or elsewhere in the code base.
    // -----------------------------------------------------------------------
}
