static public File allocateFile(File dir, String name) {
    if (dir == null) {
        throw new IllegalArgumentException("Target directory must not be null");
    }
    if (name == null) {
        throw new IllegalArgumentException("File name must not be null");
    }

    // Remove query part after '?'
    int q = name.indexOf('?');
    if (q >= 0) {
        name = name.substring(0, q);
    }

    // Normalize path to prevent traversal
    Path basePath = dir.toPath().toAbsolutePath().normalize();
    Path targetPath = basePath.resolve(name).normalize();

    if (!targetPath.startsWith(basePath)) {
        throw new IllegalArgumentException("Invalid file name: path traversal detected");
    }

    File file = targetPath.toFile();

    // Ensure unique file name if already exists
    String fileName = file.getName();
    int dot = fileName.lastIndexOf('.');
    String prefix = dot < 0 ? fileName : fileName.substring(0, dot);
    String suffix = dot < 0 ? "" : fileName.substring(dot);
    int index = 2;
    while (file.exists()) {
        // Build new file name preserving parent directory
        String newName = prefix + "-" + index++ + suffix;
        file = new File(file.getParentFile(), newName);
    }

    // Create parent directories safely
    File parent = file.getParentFile();
    if (parent != null && !parent.mkdirs() && !parent.isDirectory()) {
        throw new IllegalStateException("Failed to create directories: " + parent);
    }

    return file;
}
