/**
 * FactoryBean that creates a {@link SecureRandom} instance.
 *
 * <p>The original implementation seeded the {@code SecureRandom} with data read from a
 * {@link Resource}.  Using externally supplied seed material is insecure because an attacker
 * could influence the seed and thus predict the generated random values.  The patched version
 * removes this behaviour and relies exclusively on the built‑in, platform‑provided seeding
 * mechanism, which draws entropy from the operating system.</p>
 *
 * <p>If a custom algorithm is configured but is not available, the factory falls back to the
 * default {@code SecureRandom} implementation to guarantee that a functional instance is
 * always returned.</p>
 */
public class SecureRandomFactoryBean implements FactoryBean<SecureRandom> {

    /** Default algorithm – kept for backward compatibility but not mandatory. */
    private String algorithm = "SHA1PRNG";

    /** Optional seed resource – retained for API compatibility but ignored for security. */
    private Resource seed;

    // -----------------------------------------------------------------------
    // FactoryBean contract
    // -----------------------------------------------------------------------

    @Override
    public SecureRandom getObject() throws Exception {
        SecureRandom rnd = createSecureRandomInstance();

        // Force the internal seeding process (some JDKs delay seeding until first use).
        // The generated byte is discarded; its sole purpose is to ensure the RNG is
        // fully initialized before being handed to callers.
        rnd.nextBytes(new byte[1]);

        // NOTE: The external seed is deliberately NOT used.  If a seed is supplied we
        // simply ignore it to avoid weakening the randomness.  Keeping the field allows
        // existing configuration files to remain valid without breaking functionality.
        return rnd;
    }

    @Override
    public Class<?> getObjectType() {
        return SecureRandom.class;
    }

    @Override
    public boolean isSingleton() {
        // Each call returns a freshly‑initialized SecureRandom instance.
        return false;
    }

    // -----------------------------------------------------------------------
    // Helper methods
    // -----------------------------------------------------------------------

    /**
     * Creates a {@link SecureRandom} instance using the configured algorithm.
     * If the algorithm is {@code null}, empty, or not available, the method falls back
     * to the default constructor, which selects the strongest provider available on the
     * platform.
     *
     * @return a securely seeded SecureRandom instance
     */
    private SecureRandom createSecureRandomInstance() {
        if (algorithm == null || algorithm.trim().isEmpty()) {
            // No algorithm specified – let the JDK choose the best default.
            return new SecureRandom();
        }

        try {
            return SecureRandom.getInstance(algorithm);
        } catch (NoSuchAlgorithmException ex) {
            // Configured algorithm is not present.  Log the problem (if a logger is available)
            // and fall back to the default implementation to guarantee functionality.
            // For this snippet we simply fallback; in a real application you would log.
            return new SecureRandom();
        }
    }

    // -----------------------------------------------------------------------
    // Property setters (used by Spring for configuration)
    // -----------------------------------------------------------------------

    public void setAlgorithm(String algorithm) {
        this.algorithm = algorithm;
    }

    public void setSeed(Resource seed) {
        this.seed = seed;
    }
