 *
 * This method creates a new {@link TransformerFactory} for each call,
 * configures it for secure processing, disables access to external DTDs
 * and stylesheets, validates the input stream, and ensures proper resource
 * handling.
 */
private static Transformer createTransformer(InputStream templateStream) throws IOException {
    if (templateStream == null) {
        throw new IllegalArgumentException("templateStream must not be null");
    }

    // Create a fresh factory instance to avoid shared mutable state.
    TransformerFactory factory = TransformerFactory.newInstance();

    try {
        // Enable secure processing to limit resource consumption and
        // prevent many classes of XSLT attacks.
        factory.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);

        // Completely block external entity resolution (DTD) and external
        // stylesheet imports/includes.
        factory.setAttribute(XMLConstants.ACCESS_EXTERNAL_DTD, "");
        factory.setAttribute(XMLConstants.ACCESS_EXTERNAL_STYLESHEET, "");
    } catch (TransformerConfigurationException | IllegalArgumentException e) {
        // Configuration failures are critical – wrap and re‑throw.
        throw new ProcessingFailedException("Failed to configure secure TransformerFactory", e);
    }

    // Use try‑with‑resources to guarantee the InputStream is closed.
    try (InputStream is = templateStream) {
        StreamSource source = new StreamSource(is);
        // Prevent the processor from resolving relative URIs.
        source.setSystemId("");

        return factory.newTransformer(source);
    } catch (TransformerConfigurationException e) {
        // Wrap any XSLT compilation errors.
        throw new ProcessingFailedException("Failed to create XSLT transformer", e);
    }
}
