private void expand(ArchiveEntrySupplier supplier, EntryWriter writer, File targetDirectory) throws IOException {
    Path targetPath = targetDirectory.toPath().toRealPath(LinkOption.NOFOLLOW_LINKS);
    ArchiveEntry entry = supplier.getNextReadableEntry();
    while (entry != null) {
        String entryName = entry.getName();
        if (entryName == null) {
            throw new IOException("Archive entry name is null");
        }

        // Reject absolute paths
        if (entryName.startsWith("/") || entryName.matches("^[a-zA-Z]:\\\\.*")) {
            throw new IOException("Entry name '" + entryName + "' is absolute");
        }

        // Normalize the entry path to eliminate ".." and "." components
        Path normalizedEntryPath = Paths.get(entryName).normalize();

        // After normalization the path must not start with ".."
        if (normalizedEntryPath.startsWith("..")) {
            throw new IOException("Entry name '" + entryName + "' attempts path traversal");
        }

        // Resolve against the target directory and obtain the real path
        Path resolvedPath = targetPath.resolve(normalizedEntryPath).normalize();

        // Final check that the resolved path is still inside the target directory
        if (!resolvedPath.startsWith(targetPath)) {
            throw new IOException("Expanding entry '" + entryName + "' would create file outside of " + targetDirectory);
        }

        File f = resolvedPath.toFile();

        if (entry.isDirectory()) {
            // Create directory (including any missing parents) without following symlinks
            Files.createDirectories(resolvedPath);
            // Verify that the created directory is still inside the target directory
            if (!resolvedPath.toRealPath(LinkOption.NOFOLLOW_LINKS).startsWith(targetPath)) {
                throw new IOException("Created directory '" + f + "' is outside of target directory");
            }
        } else {
            // Ensure parent directory exists
            Path parentPath = resolvedPath.getParent();
            if (parentPath != null) {
                Files.createDirectories(parentPath);
                // Verify parent after creation
                if (!parentPath.toRealPath(LinkOption.NOFOLLOW_LINKS).startsWith(targetPath)) {
                    throw new IOException("Created parent directory '" + parentPath + "' is outside of target directory");
                }
            }

            // Write file content
            try (OutputStream out = Files.newOutputStream(resolvedPath,
                    StandardOpenOption.CREATE,
                    StandardOpenOption.TRUNCATE_EXISTING,
                    StandardOpenOption.WRITE)) {
                writer.writeEntryDataTo(entry, out);
            }
        }

        entry = supplier.getNextReadableEntry();
    }
}
