private int readStored(final byte[] buffer, final int offset, final int length) throws IOException {
    if (current.hasDataDescriptor) {
        if (lastStoredEntry == null) {
            readStoredEntry();
        }
        return lastStoredEntry.read(buffer, offset, length);
    }

    final long csize = current.entry.getSize();
    if (csize < 0) {
        throw new IOException("Stored entry size is unknown or negative: " + csize);
    }

    // If we have already read the declared size, signal EOF
    if (current.bytesRead >= csize) {
        return -1;
    }

    // Ensure we have data in the internal buffer
    if (buf.position() >= buf.limit()) {
        buf.clear(); // position=0, limit=capacity
        int l = in.read(buf.array());
        if (l == -1) {
            // Unexpected end of underlying stream before declared size
            return -1;
        }
        if (l == 0) {
            // Defensive: treat as EOF to avoid infinite loop
            return -1;
        }
        buf.limit(l);
        count(l);
        current.bytesReadFromStream += l;
    }

    // Determine the maximum number of bytes we are allowed to return
    int maxAllowed = (int) Math.min(buf.remaining(), length);
    long remainingEntry = csize - current.bytesRead;
    if (remainingEntry < maxAllowed) {
        maxAllowed = (int) remainingEntry;
    }

    if (maxAllowed <= 0) {
        return -1;
    }

    buf.get(buffer, offset, maxAllowed);
    current.bytesRead += maxAllowed;
    return maxAllowed;
}
