            // -----------------------------------------------------------------
            //  a) Safety net – too many iterations → give up.
            // -----------------------------------------------------------------
            if (++iterationCount > CEIL_MAX_ITERATIONS) {
                throw new RareOrImpossibleDateException(
                        "Ceiling algorithm exceeded safe iteration limit (" + CEIL_MAX_ITERATIONS + ").");
            }

            // -----------------------------------------------------------------
            //  b) If we have moved beyond the two‑year horizon, the date is
            //     considered too rare / impossible.
            // -----------------------------------------------------------------
            if (cal.compareTo(twoYearsFuture) > 0) {
                throw new RareOrImpossibleDateException();
            }

            // -----------------------------------------------------------------
            //  c) Detect a complete stall: the calendar state is identical to
            //     the one at the start of the previous outer iteration.
            // -----------------------------------------------------------------
            if (previousSnapshot != null && calendarsEqual(cal, previousSnapshot)) {
                throw new RareOrImpossibleDateException(
                        "Ceiling algorithm stalled – no progress made in iteration " + iterationCount + ".");
            }
            // Remember the current state for the next stall‑check.
            previousSnapshot = (Calendar) cal.clone();

            // -----------------------------------------------------------------
            //  d) Core adjustment logic – unchanged except for the added
            //     continue OUTER statements that now respect the outer‑loop guard.
            // -----------------------------------------------------------------
