public class XPathBuilder extends ServiceSupport implements Expression, Predicate, NamespaceAware {

    private final ThreadLocal<Exchange> exchange = new ThreadLocal<Exchange>();
    private volatile Class<?> documentType = Document.class;

    // -------------------------------------------------------------------------
    // Other methods (omitted for brevity)
    // -------------------------------------------------------------------------

    /**
     * Securely obtains a document (or other supported representation) from the
     * given body. XML external entity processing is disabled to prevent XXE attacks.
     */
    protected Object doGetDocument(Exchange exchange, Object body) throws Exception {
        if (body == null) {
            return null;
        }

        Object answer = null;
        Class<?> type = getDocumentType();
        Exception cause = null;

        // First try the Camel type converter (if a target type is configured)
        if (type != null) {
            try {
                answer = exchange.getContext().getTypeConverter().convertTo(type, exchange, body);
            } catch (Exception e) {
                cause = e; // remember the cause for later if we cannot obtain a result
            }
        }

        // If conversion did not succeed, handle the known body types ourselves
        if (answer == null) {
            if (body instanceof WrappedFile) {
                // Convert to InputStream and parse securely into a Document
                try (InputStream is = exchange.getContext().getTypeConverter()
                        .convertTo(InputStream.class, exchange, body)) {
                    if (is != null) {
                        answer = parseSecureDocument(is);
                    }
                }
            } else if (body instanceof BeanInvocation) {
                BeanInvocation bi = exchange.getContext().getTypeConverter()
                        .convertTo(BeanInvocation.class, exchange, body);
                if (bi.getArgs() != null && bi.getArgs().length == 1 && bi.getArgs()[0] == null) {
                    answer = null;
                }
            } else if (body instanceof String) {
                // Parse the XML string securely into a Document
                String xml = (String) body;
                try (StringReader sr = new StringReader(xml)) {
                    answer = parseSecureDocument(sr);
                }
            }
        }

        // If no specific document type is required and we still have no answer,
        // fall back to returning the original body.
        if (type == null && answer == null) {
            answer = body;
        } else if (answer == null) {
            // We tried everything but still have no result – re‑throw the original cause
            // or a generic conversion exception.
            if (cause != null) {
                throw cause;
            } else {
                throw new NoTypeConversionAvailableException(body, type);
            }
        }

        return answer;
    }

    /**
     * Parses XML from an {@link InputStream} into a {@link Document} with all
     * external entity processing disabled.
     */
    private Document parseSecureDocument(InputStream is) throws Exception {
        DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();
        // ---- Secure configuration to prevent XXE ----
        dbf.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);
        dbf.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
        dbf.setFeature("http://xml.org/sax/features/external-general-entities", false);
        dbf.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
        dbf.setXIncludeAware(false);
        dbf.setExpandEntityReferences(false);
        dbf.setNamespaceAware(true);
