     * Creates a secure {@link XMLStreamReader} that is protected against XML External Entity (XXE) attacks.
     *
     * @param inputStream the raw XML input stream
     * @return a configured {@link XMLStreamReader}
     * @throws XMLStreamException if the underlying parser cannot be created
     * @throws IOException        if an I/O error occurs while wrapping the stream
     */
    private static final XMLStreamReader createXMLStreamReader(InputStream inputStream)
            throws XMLStreamException, IOException {

        XMLInputFactory factory = XMLInputFactory.newInstance();

        /* -------------------------------------------------------------
         * Harden the factory against XXE.
         *
         * 1. Disable DTD processing (SUPPORT_DTD = false).  This
         *    prevents the parser from loading any DTD, which is the
         *    primary vector for external entity definitions.
         *
         * 2. Disable external entity resolution
         *    (IS_SUPPORTING_EXTERNAL_ENTITIES = false).  Even if a DTD
         *    were somehow processed, the parser will not resolve any
         *    external entities referenced within it.
         *
         * Some XMLInputFactory implementations may not support these
         * properties and will throw IllegalArgumentException.  In that
         * case we fall back to the default (secure) behaviour, but we
         * log the situation for debugging purposes.
         * ------------------------------------------------------------- */
        try {
            factory.setProperty(XMLInputFactory.SUPPORT_DTD, Boolean.FALSE);
        } catch (IllegalArgumentException ignored) {
            // Property not supported – the implementation is likely already secure.
        }

        try {
            factory.setProperty(XMLInputFactory.IS_SUPPORTING_EXTERNAL_ENTITIES, Boolean.FALSE);
        } catch (IllegalArgumentException ignored) {
            // Property not supported – the implementation is likely already secure.
        }

        // Preserve existing behaviour that is required by the application.
        factory.setProperty(XMLInputFactory.IS_COALESCING, Boolean.TRUE);
        factory.setProperty(XMLInputFactory.IS_REPLACING_ENTITY_REFERENCES, Boolean.TRUE);

        // Wrap the original stream (e.g., to strip a possible XML declaration prefix)
        InputStream safeStream = wrapPrefixRemovingInputStream(inputStream);

        return factory.createXMLStreamReader(safeStream);
