import org.apache.commons.io.IOUtils;
import org.cloudfoundry.identity.uaa.scim.ScimUser;
import org.cloudfoundry.identity.uaa.scim.ScimUserProvisioning;
import org.cloudfoundry.identity.uaa.scim.exception.ScimResourceNotFoundException;
import org.cloudfoundry.identity.uaa.util.JsonUtils;
import org.cloudfoundry.identity.uaa.util.UaaUrlUtils;
import org.cloudfoundry.identity.uaa.zone.IdentityZoneHolder;
import org.springframework.security.core.Authentication;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.security.core.userdetails.UserDetails;

import javax.servlet.http.HttpServletRequest;
import java.io.IOException;

/**
 * Checks whether a self‑update request for a {@link ScimUser} is allowed.
 *
 * <p>
 * The original implementation only compared the values in the request body with the
 * values stored in the database.  This allowed an attacker to change another
 * user's e‑mail address (or other fields) by simply sending a crafted request that
 * matched the target user's current values.  The patched version adds a strict
 * ownership check: the authenticated principal must be the same user whose ID appears
 * in the request URL.  If the principal cannot be determined or does not match,
 * the update is rejected.
 * </p>
 */
public class ScimUserSelfUpdateAllowed {

    public static final int USER_ID_PATH_PARAMETER_INDEX = 1;
    private final ScimUserProvisioning scimUserProvisioning;

    public ScimUserSelfUpdateAllowed(ScimUserProvisioning scimUserProvisioning) {
        this.scimUserProvisioning = scimUserProvisioning;
    }

    /**
     * Returns {@code true} if the request is a legitimate self‑update, {@code false}
     * otherwise.
     *
     * @param request the incoming HTTP request
     * @return {@code true} if the update is allowed
     * @throws IOException if the request body cannot be read
     */
    public boolean isAllowed(HttpServletRequest request) throws IOException {

        // 1️⃣  Extract the authenticated user identifier.
        String authenticatedUserId = extractAuthenticatedUserId(request);
        if (authenticatedUserId == null) {
            // No authenticated principal – deny the operation.
            return false;
        }

        // 2️⃣  Extract the user ID from the request path (the user being modified).
        String targetUserId = UaaUrlUtils.extractPathVariableFromUrl(
                USER_ID_PATH_PARAMETER_INDEX,
                UaaUrlUtils.getRequestPath(request));

        // 3️⃣  The caller must be the owner of the target account.
        if (!authenticatedUserId.equals(targetUserId)) {
            return false;
        }

        // 4️⃣  Parse the incoming payload.
        String requestBody = IOUtils.toString(request.getReader());
        ScimUser scimUserFromRequest = JsonUtils.readValue(requestBody, ScimUser.class);

        // 5️⃣  Load the current user record from the DB.
        String zoneId = IdentityZoneHolder.get().getId();
        ScimUser scimUserFromDb;
        try {
            scimUserFromDb = scimUserProvisioning.retrieve(targetUserId, zoneId);
        } catch (ScimResourceNotFoundException e) {
            // If the user does not exist we cannot safely allow an update.
            return false;
        }

        // 6️⃣  Verify that immutable fields have not been tampered with.
        // These checks remain unchanged but are now performed only after the
        // ownership validation above.
        if (!safeEquals(scimUserFromDb.getPrimaryEmail(), scimUserFromRequest.getPrimaryEmail())) {
            return false;
        }
        if (!safeEquals(scimUserFromDb.getUserName(), scimUserFromRequest.getUserName())) {
            return false;
        }
        if (scimUserFromDb.isVerified() != scimUserFromRequest.isVerified()) {
            return false;
        }
        if (scimUserFromDb.isActive() != scimUserFromRequest.isActive()) {
            return false;
        }
        if (!safeEquals(scimUserFromDb.getOrigin(), scimUserFromRequest.getOrigin())) {
            return false;
        }

        // All checks passed – the self‑update is allowed.
        return true;
    }

    /**
     * Retrieves the authenticated user identifier from the current security context
     * or, as a fallback, from a custom request header.
     *
     * @param request the incoming HTTP request
     * @return the user ID of the authenticated principal, or {@code null} if it cannot be determined
     */
    private String extractAuthenticatedUserId(HttpServletRequest request) {
        // Primary source: Spring Security context.
        Authentication authentication = SecurityContextHolder.getContext().getAuthentication();
        if (authentication != null && authentication.isAuthenticated()) {
            Object principal = authentication.getPrincipal();
            if (principal instanceof UserDetails) {
                // In many UAA deployments the username is the unique user ID.
                return ((UserDetails) principal).getUsername();
            }
            if (principal instanceof String) {
                return (String) principal;
            }
        }

        // Fallback: a dedicated header that upstream components may set.
        // This header is optional and only used when the security context is unavailable.
        String header = request.getHeader("X-Authenticated-User-Id");
        return (header != null && !header.isEmpty()) ? header : null;
    }

    /**
     * Null‑safe string comparison.
     */
    private boolean safeEquals(String a, String b) {
        return (a == null) ? b == null : a.equals(b);
    }

    // other methods (unchanged)
}
